INSERT INTO `cvs` VALUES (8,2,'CV2','Trần Thị Buoi','\n          <article class=\"cv-page cv-page-cv2\">\n            <section class=\"cv-hero cv-hero-cv2\">\n              <div class=\"cv-intro cv-intro-dark\" bis_skin_checked=\"1\">\n                <p class=\"cv-kicker\">Professional Profile</p>\n                <h1 class=\"cv-title\" data-editable=\"\" data-template-title=\"\" contenteditable=\"true\" spellcheck=\"false\" data-value=\"Trần Thị Buoi\">Trần Thị Buoi</h1>\n                <p class=\"cv-subtitle\" data-editable=\"\" contenteditable=\"true\" spellcheck=\"false\">Business Analyst</p>\n                <p class=\"file-note\" data-no-export=\"\">\n                  Bấm vào nội dung để chỉnh sửa trực tiếp. Phần trợ giúp và nút thao tác sẽ không nằm trong PDF.\n                </p>\n              </div>\n\n              <div class=\"avatar-wrap avatar-wrap-right\" bis_skin_checked=\"1\">\n                <img class=\"avatar-image avatar-image-cv2\" data-photo-preview=\"\" src=\"https://randomuser.me/api/portraits/women/44.jpg\" alt=\"Ảnh CV\">\n                <label class=\"btn btn-outline photo-input\" data-no-export=\"\">\n                  Thêm ảnh\n                  <input type=\"file\" accept=\"image/*\" data-photo-input=\"\" style=\"width:1px;height:1px;opacity:0;position:absolute;pointer-events:none;\">\n                </label>\n              </div>\n            </section>\n\n            <section class=\"cv-two-col\">\n              <div class=\"cv-left-col\" bis_skin_checked=\"1\">\n                <section class=\"cv-section cv-section-card cv-section-dark\">\n                  <h3>Thông tin liên hệ</h3>\n                  <div class=\"cv-grid-2 cv-grid-compact\" bis_skin_checked=\"1\">\n                    <div class=\"editable\" data-editable=\"\" contenteditable=\"true\" spellcheck=\"false\" bis_skin_checked=\"1\">? tranthib@example.com</div>\n                    <div class=\"editable\" data-editable=\"\" contenteditable=\"true\" spellcheck=\"false\" bis_skin_checked=\"1\">? 0987 654 321</div>\n                    <div class=\"editable\" data-editable=\"\" contenteditable=\"true\" spellcheck=\"false\" bis_skin_checked=\"1\">? TP. Hồ Chí Minh, Việt Nam</div>\n                    <div class=\"editable\" data-editable=\"\" contenteditable=\"true\" spellcheck=\"false\" bis_skin_checked=\"1\">? linkedin.com/in/tranthib</div>\n                  </div>\n                </section>\n\n                <section class=\"cv-section cv-section-card cv-section-dark\">\n                  <h3>Kỹ năng</h3>\n                  <div class=\"editable\" data-editable=\"\" contenteditable=\"true\" spellcheck=\"false\" bis_skin_checked=\"1\">\n                    <ul class=\"cv-list\">\n                      <li>Phân tích yêu cầu</li>\n                      <li>SQL / Data Reporting</li>\n                      <li>UI/UX Review</li>\n                      <li>Agile / Scrum</li>\n                    </ul>\n                  </div>\n                </section>\n\n                <section class=\"cv-section cv-section-card cv-section-dark\">\n                  <h3>Học vấn</h3>\n                  <div class=\"cv-grid-2 cv-grid-compact\" bis_skin_checked=\"1\">\n                    <div class=\"editable\" data-editable=\"\" contenteditable=\"true\" spellcheck=\"false\" bis_skin_checked=\"1\"><strong>Đại học Kinh tế Quốc dân</strong></div>\n                    <div class=\"editable\" data-editable=\"\" contenteditable=\"true\" spellcheck=\"false\" bis_skin_checked=\"1\">Hệ thống thông tin quản lý, 2017 - 2021</div>\n                    <div class=\"editable\" data-editable=\"\" contenteditable=\"true\" spellcheck=\"false\" bis_skin_checked=\"1\">GPA: 3.75/4.0</div>\n                  </div>\n                </section>\n              </div>\n\n              <div class=\"cv-right-col\" bis_skin_checked=\"1\">\n                <section class=\"cv-section cv-section-card cv-section-dark\">\n                  <h3>Mục tiêu nghề nghiệp</h3>\n                  <div class=\"editable\" data-editable=\"\" contenteditable=\"true\" spellcheck=\"false\" bis_skin_checked=\"1\">\n                    Mong muốn trở thành chuyên viên phân tích nghiệp vụ có khả năng kết nối yêu cầu kinh doanh với giải pháp công nghệ, tối ưu quy trình và nâng cao hiệu quả vận hành.\n                  </div>\n                </section>\n\n                <section class=\"cv-section cv-section-card cv-section-dark\">\n                  <h3>Kinh nghiệm làm việc</h3>\n                  <div class=\"cv-stack\" bis_skin_checked=\"1\">\n                    <div class=\"cv-experience\" bis_skin_checked=\"1\">\n                      <div class=\"editable\" data-editable=\"\" contenteditable=\"true\" spellcheck=\"false\" bis_skin_checked=\"1\"><strong>Công ty DEF</strong> - Business Analyst (2021 - 2024)</div>\n                      <div class=\"editable\" data-editable=\"\" contenteditable=\"true\" spellcheck=\"false\" bis_skin_checked=\"1\">Thu thập yêu cầu, phân tích quy trình và phối hợp cùng đội phát triển để triển khai tính năng.</div>\n                    </div>\n                    <div class=\"cv-experience\" bis_skin_checked=\"1\">\n                      <div class=\"editable\" data-editable=\"\" contenteditable=\"true\" spellcheck=\"false\" bis_skin_checked=\"1\"><strong>Công ty XYZ</strong> - Intern Analyst (2020 - 2021)</div>\n                      <div class=\"editable\" data-editable=\"\" contenteditable=\"true\" spellcheck=\"false\" bis_skin_checked=\"1\">Hỗ trợ lập tài liệu nghiệp vụ, phân tích dữ liệu và kiểm thử các luồng chính của hệ thống.</div>\n                    </div>\n                  </div>\n                </section>\n\n                <section class=\"cv-section cv-section-card cv-section-dark\">\n                  <h3>Dự án tiêu biểu</h3>\n                  <div class=\"editable\" data-editable=\"\" contenteditable=\"true\" spellcheck=\"false\" bis_skin_checked=\"1\">\n                    Tham gia xây dựng hệ thống quản lý hồ sơ, dashboard dữ liệu và công cụ theo dõi tiến độ cho nhiều nhóm nội bộ.\n                  </div>\n                </section>\n              </div>\n            </section>\n          </article>\n        ',2,'2026-06-13 16:18:32','2026-06-13 16:18:32'),(9,1,'CV1','CV chưa có tiêu đề','{\"fullName\":\"HENRY JONES\",\"title\":\"Lead Sales Operations Manager\",\"email\":\"resume@example.com\",\"phone\":\"(512) 555-0199\",\"address\":\"Austin, TX, 78701\",\"summary\":\"Results-oriented Retail Operations Specialist with over 5 years of experience in high-volume consumer environments. Expert in inventory management, visual merchandising, and team leadership.\",\"skills\":[\"Strategic Upselling\",\"Visual Merchandising\",\"Inventory Reconciliation\",\"Conflict Resolution\"],\"exp1_title\":\"Lead Sales Coordinator\",\"exp1_date\":\"Apr 2022 — Current\",\"exp1_company\":\"HomeGoods Solutions, Austin, TX\",\"exp1_achievements\":[\"Executed comprehensive loss prevention protocols to identify security vulnerabilities and decrease annual inventory shrinkage by 12%.\",\"Facilitated weekly training workshops for 15+ staff members on advanced closing techniques.\"],\"exp2_title\":\"Retail Sales Specialist\",\"exp2_date\":\"Jul 2021 — Apr 2022\",\"exp2_company\":\"Global Apparel Corp, Austin, TX\",\"exp2_achievements\":[\"Managed inventory replenishment cycles to ensure 100% availability of core product lines during peak seasonal periods.\",\"Direct department aesthetics by implementing corporate style guides to maintain premium brand positioning.\"],\"edu_title\":\"Bachelor of Science, Marketing\",\"edu_date\":\"Sep 2011 — May 2015\",\"edu_school\":\"University of Texas at Austin, Austin, TX\"}',NULL,'2026-07-03 08:24:09','2026-07-03 08:24:09'),(10,1,'CV1','CV chưa có tiêu đề','{\"fullName\":\"HENRY JONES\",\"title\":\"Lead Sales Operations Manager\",\"email\":\"resume@example.com\",\"phone\":\"(512) 555-0199\",\"address\":\"Austin, TX, 78701\",\"summary\":\"Results-o