INSERT INTO `templates` VALUES (9,'henry_simple','Henry Jones - Simple','Đơn giản · 1 cột','Mẫu CV bố cục 1 cột, rõ ràng, tập trung vào nội dung.','https://picsum.photos/id/20/400/280',0,0,'2026-07-09 17:05:21'),(10,'henry_professional','Henry Jones - Professional','Chuyên nghiệp · 2 cột','Mẫu CV 2 cột, hiện đại, nổi bật kỹ năng và thông tin.','https://picsum.photos/id/21/400/280',0,0,'2026-07-09 17:05:21'),(11,'henry_traditional','Henry Jones - Traditional','Cổ điển · Trang trọng','Mẫu CV truyền thống, phù hợp vị trí quản lý cấp cao.','https://picsum.photos/id/22/400/280',1,0,'2026-07-09 17:05:21'),(12,'henry_modern','Henry Jones - Modern','Sáng tạo · Nổi bật','Mẫu CV màu sắc nổi bật, phù hợp ngành sáng tạo.','https://picsum.photos/id/23/400/280',1,0,'2026-07-09 17:05:21');
